function bucket(e){let s=[];switch(e){case 0:case 1:case 2:case 3:s.push("low");break;case 4:case 5:case 6:case 7:case 8:case 9:s.push("mid-low");break;case 10:s.push("ten");case 11:s.push("ten-or-eleven");break;case 12:case 13:case 14:case 15:case 16:case 17:case 18:case 19:case 20:case 21:s.push("teens-twenties");break;default:s.push("other");break;case 22:case 23:case 24:case 25:case 26:case 27:case 28:case 29:case 30:s.push("high-twenties");break;case 31:case 32:case 33:case 34:case 35:s.push("thirties");break;case 36:case 37:case 38:case 39:s.push("late-thirties")}return s.join("+")}for(const e of[0,3,4,9,10,11,12,21,22,30,31,35,36,39,-5,40,1e3])print(e,"=>",bucket(e));